function run() {
  ObjC.import("AppKit");
  ObjC.import("CoreGraphics");

  const mouse = $.NSEvent.mouseLocation;
  const screens = $.NSScreen.screens;
  const mainDisplayID = Number($.CGMainDisplayID());
  let primaryScreen = undefined;

  for (let i = 0; i < screens.count; i++) {
    const screen = screens.objectAtIndex(i);
    const screenNumber = screen.deviceDescription.objectForKey("NSScreenNumber");
    if (Number(ObjC.unwrap(screenNumber)) === mainDisplayID) {
      primaryScreen = screen;
      break;
    }
  }

  if (primaryScreen === undefined && screens.count > 0) {
    primaryScreen = screens.objectAtIndex(0);
  }
  if (primaryScreen === undefined) {
    throw new Error("No screens found");
  }

  const frame = primaryScreen.frame;
  return JSON.stringify({
    x: Math.trunc(mouse.x - frame.origin.x),
    y: Math.trunc(frame.origin.y + frame.size.height - mouse.y),
  });
}

